#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "blosc.h"

int main() {
    // Initialize blosc
    blosc_init();
    blosc_set_compressor("blosclz");
    blosc_set_blocksize(256);

    // Create some test data
    int nbytes = 1000;
    int typesize = 4;
    char* data = malloc(nbytes);
    for (int i = 0; i < nbytes/4; i++) {
        ((int*)data)[i] = i;
    }

    // Compress
    int maxdest = nbytes + BLOSC_MAX_OVERHEAD;
    char* compressed = malloc(maxdest);
    int cbytes = blosc_compress(9, 1, typesize, nbytes, data, compressed, maxdest);
    printf("Compressed %d bytes to %d bytes\n", nbytes, cbytes);

    // Write to file
    FILE* f = fopen("/tmp/valid.cdata", "wb");
    fwrite(compressed, 1, cbytes, f);
    fclose(f);

    // Print header
    unsigned char* hdr = (unsigned char*)compressed;
    printf("Header: ");
    for (int i = 0; i < 32; i++) {
        printf("%02x ", hdr[i]);
    }
    printf("\n");
    printf("version=%d, versionlz=%d, flags=%d, typesize=%d\n", hdr[0], hdr[1], hdr[2], hdr[3]);
    printf("nbytes=%d, blocksize=%d, cbytes=%d\n", 
           *(int*)(hdr+4), *(int*)(hdr+8), *(int*)(hdr+12));

    // Decompress to verify
    char* decompressed = malloc(nbytes);
    int dlen = blosc_decompress(compressed, decompressed, nbytes);
    printf("Decompressed to %d bytes\n", dlen);

    blosc_destroy();
    free(data);
    free(compressed);
    free(decompressed);
    return 0;
}
